-- ABWEHR CITY: Violetta with inward opening is a separate construction.
begin;
on conflict(slug) do update set name=excluded.name,description=excluded.description,features=excluded.features,image_path=excluded.image_path;
on conflict(product_slug,label) do update set value=excluded.value,sort_order=excluded.sort_order,is_active=true;
on conflict do nothing;
commit;
select count(*) as моделей,count(*) filter(where is_available) as опубліковано,(select count(*) from public.product_media where product_slug='abwehr-city-violetta-inward-opening' and kind='gallery') as фото_в_галереях from public.products where slug='abwehr-city-violetta-inward-opening';
